{"filename":"models.py","content":"import os
import sqlite3
from flask import g, current_app

def get_db():
    if 'db' not in g:
        db_path = os.path.join(current_app.instance_path, 'cycletracker.sqlite')
        os.makedirs(os.path.dirname(db_path), exist_ok=True)
        g.db = sqlite3.connect(db_path, detect_types=sqlite3.PARSE_DECLTYPES)
        g.db.row_factory = sqlite3.Row
    return g.db

def close_db(e=None):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = get_db()
    cursor = db.cursor()
    cursor.executescript("""CREATE TABLE IF NOT EXISTS periodlog (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        start_date TEXT NOT NULL,
        end_date TEXT NOT NULL,
        flow TEXT,
        symptoms TEXT,
        notes TEXT
    );
    CREATE TABLE IF NOT EXISTS cycle (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        cycle_number INTEGER NOT NULL,
        average_length INTEGER,
        average_flow TEXT
    );
    CREATE TABLE IF NOT EXISTS reminder (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        date TEXT NOT NULL,
        type TEXT NOT NULL,
        message TEXT
    );
    """)
    db.commit()

def init_app(app):
    app.teardown_appcontext(close_db)
    with app.app_context():
        init_db()"}
